css += '  body{background:#fff}\n  .app-shell{display:block;padding:0}\n  .app-main{max-width:100%}\n  .card{box-shadow:none;border:1px solid #ccc;break-inside:avoid}\n  .item-card{break-inside:avoid}\n';
