// ── HTML déterministe ─────────────────────────────────────────────────────
var htmlSections = '';
// ── Axe 1 : relations N-N (champ « <autre>_ids ») ─────────────────────────
// Le backend (V6.16+) crée une table de jointure + endpoints GET/POST/DELETE
// /<from>/:id/<autre> { <autre>_id }. Ici on exclut ces champs du formulaire
// de création (ce ne sont pas de simples inputs) et on branche un panneau de
// liaison dans la modale détail, aligné sur ce contrat.
var _storeNamesAll = resources.map(function(rr){ return rr.storeName; });
function _isManyRel(name){ return /_ids$/.test(String(name || '')) && name !== 'ids'; }
function _relsOf(sn, fields){
  return Object.keys(fields || {}).filter(_isManyRel).map(function(k){
    var base = k.replace(/_ids$/, '');
    var otherStore = _storeNamesAll.indexOf(base + 's') >= 0 ? base + 's'
                   : (_storeNamesAll.indexOf(base) >= 0 ? base : base + 's');
    return { field: k, other: base, otherStore: otherStore, from: sn };
  });
}
var _allManyRels = {};
// Axe 1 — champs optionnels : on rend TOUS les champs métier (hors système et
// hors _ids), en marquant « optionnel » ceux qui ne sont PAS dans required_fields.
// Repli (aucun required_fields) : tous requis (comportement inchangé). Aligné sur
// le backend, qui valide/insère les optionnels seulement s'ils sont fournis.
function _renderFieldsOf(r){
  var _sys = ['id','created_at','updated_at','status'];
  var model = Object.keys(r.fields || {}).filter(function(k){ return _sys.indexOf(k) < 0 && !_isManyRel(k); });
  if (!r.required || !r.required.length) return model;
  var reqd = r.required.filter(function(k){ return !_isManyRel(k); });
  var opt  = model.filter(function(k){ return reqd.indexOf(k) < 0; });
  return reqd.concat(opt); // requis d'abord, puis optionnels
}
// Lot UI moderne — colonnes filtrables cote UI (miroir de la liste blanche backend) :
// enum -> select ; boolean -> Oui/Non ; number -> min/max. created_at gere a part.
function _filterMeta(r){
  var _sys = ['id','created_at','updated_at','status'];
  var out = [];
  Object.keys(r.fields || {}).filter(function(k){ return _sys.indexOf(k) < 0 && !_isManyRel(k); }).forEach(function(f){
    var c = classifyField(f, r.fields[f]);
    if (c.kind === 'enum') out.push({ col: f, type: 'enum', values: (c.values || []).map(String) });
    else if (c.kind === 'boolean') out.push({ col: f, type: 'boolean' });
    else if (c.kind === 'number') out.push({ col: f, type: 'number' });
  });
  return out;
}
function _isOptionalFront(r, f){ return !!(r.required && r.required.length > 0) && r.required.indexOf(f) < 0; }

resources.forEach(function(r) {
  var sn = r.storeName;
  var label = sn.charAt(0).toUpperCase() + sn.slice(1);
  var reqFields = _renderFieldsOf(r);
  var _relsHere = _relsOf(sn, r.fields);
  if (_relsHere.length) _allManyRels[sn] = _relsHere;

  if (r.postEp) {
    htmlSections += '\n    <section class="card" id="section-create-' + sn + '">';
    htmlSections += '\n      <h2 class="card-title">\u270f\ufe0f Cr\u00e9er ' + sanitizeStr(label.replace(/s$/, '')) + '</h2>';
    htmlSections += '\n      <form id="form-create-' + sn + '" class="create-form" method="post" autocomplete="off">';
    reqFields.forEach(function(f) {
      var lbl = f.charAt(0).toUpperCase() + f.slice(1).replace(/_/g, ' ');
      var fl = f.toLowerCase();
      var sensitive = ['password','token','secret','key','pin'].some(function(k){ return fl.includes(k); });
      var isNum = classifyField(f, r.fields[f]).kind === 'number';
      var _opt = _isOptionalFront(r, f);          // axe 1 : champ optionnel ?
      var _reqAttr = _opt ? '' : ' required';
      // Détecter champs FK (se terminent par _id) → générer un select dynamique
      var isFK = f.endsWith('_id') && f !== 'id';
      var refStore = isFK ? f.replace(/_id$/, 's') : null; // ex: trajet_id → trajets
      // Détection de type sémantique pour une meilleure ergonomie de saisie
      var isDate  = /(date|jour|naissance|deadline|echeance|\bddebut\b|\bfin\b)/.test(fl);
      var isEmail = /(email|mail|courriel)/.test(fl);
      var isTel   = /(telephone|\btel\b|phone|mobile|portable|contact)/.test(fl) && !isFK;
      var isLong  = /(description|commentaire|message|motif|contenu|remarque|note[s]?$|detail)/.test(fl) && !isNum;
      // Bornes numériques par sémantique de champ
      // P5/#3 : classification riche (kind + min/max/unit/default)
      var _c = classifyField(f, r.fields[f]);
      var _isBool = _c.kind === 'boolean';
      var numAttrs = '';
      if (isNum) {
        if (/latitude/.test(fl))       numAttrs = ' min="-90" max="90" step="any"';
        else if (/longitude/.test(fl)) numAttrs = ' min="-180" max="180" step="any"';
        else if (/(prix|montant|cout|tarif|price|amount|salaire)/.test(fl)) numAttrs = ' min="0" step="0.01"';
        else if (/(poids|kilo|quantite|nombre|stock|age|duree)/.test(fl))   numAttrs = ' min="0" step="any"';
      }
      // #3 : bornes explicites du modèle priment sur la sémantique
      if (isNum && _c.min != null) numAttrs = numAttrs.replace(/ min="[^"]*"/, '') + ' min="' + _c.min + '"';
      if (isNum && _c.max != null) numAttrs = numAttrs.replace(/ max="[^"]*"/, '') + ' max="' + _c.max + '"';
      if (isNum && numAttrs.indexOf('step') < 0) numAttrs += ' step="any"';
      // #3 : unité affichée dans le libellé + valeur par défaut
      var _lblU = _c.unit ? (lbl + ' (' + _c.unit + ')') : lbl;
      var _hasDef = (_c.def != null && _c.def !== '');
      var _defAttr = _hasDef ? (' value="' + sanitizeStr(String(_c.def)) + '"') : '';
      htmlSections += '\n        <div class="form-group">';
      htmlSections += '\n          <label for="field-' + sn + '-' + f + '">' + sanitizeStr(_lblU) + (_opt ? ' <span class="opt-tag">(optionnel)</span>' : '') + '</label>';
      if (isFK && refStore) {
        htmlSections += '\n          <select id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" class="form-input"' + _reqAttr + '>';
        htmlSections += '\n            <option value="">' + (_opt ? '— aucun —' : 'Chargement...') + '</option>';
        htmlSections += '\n          </select>';
      } else if (_isBool) {
        // toggle (case a cocher stylisee) — pas de "required" (defaut = non coche)
        var _boolChk = (_c.def === true || _c.def === 1 || String(_c.def) === '1' || String(_c.def).toLowerCase() === 'true') ? ' checked' : '';
        htmlSections += '\n          <label class="switch"><input type="checkbox" id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '"' + _boolChk + '><span class="switch-track"><span class="switch-thumb"></span></span><span class="switch-label">Oui / Non</span></label>';
      } else if (_c.kind === 'enum') {
        htmlSections += '\n          <select id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" class="form-input"' + _reqAttr + '>';
        htmlSections += '\n            <option value="">— choisir —</option>';
        (_c.values || []).forEach(function(_ov){ var _sel = (_hasDef && String(_c.def) === String(_ov)) ? ' selected' : ''; htmlSections += '\n            <option value="' + sanitizeStr(_ov) + '"' + _sel + '>' + sanitizeStr(_ov) + '</option>'; });
        htmlSections += '\n          </select>';
      } else if (isLong || _c.kind === 'longtext') {
        htmlSections += '\n          <textarea id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '" placeholder="' + sanitizeStr(lbl) + '" class="form-input" rows="2" maxlength="5000"' + _reqAttr + '>' + (_hasDef ? sanitizeStr(String(_c.def)) : '') + '</textarea>';
      } else {
        var type, ph;
        if (sensitive)              { type = 'password';       ph = sanitizeStr(lbl); }
        else if (_c.kind === 'datetime') { type = 'datetime-local'; ph = ''; }
        else if (isDate || _c.kind === 'date') { type = 'date'; ph = ''; }   // sélecteur de date natif
        else if (isEmail || _c.kind === 'email'){ type = 'email'; ph = 'exemple@domaine.com'; }
        else if (isTel || _c.kind === 'tel')  { type = 'tel';   ph = '+229 XX XX XX XX'; }
        else if (isNum)             { type = 'number';         ph = sanitizeStr(lbl) + ' (nombre)'; }
        else                        { type = 'text';           ph = sanitizeStr(lbl); }
        htmlSections += '\n          <input type="' + type + '" id="field-' + sn + '-' + f + '" name="' + sanitizeStr(f) + '"' + (isNum ? numAttrs : '') + (sensitive ? '' : _defAttr) + ' placeholder="' + ph + '" class="form-input"' + _reqAttr + '>';
      }
      htmlSections += '\n        </div>';
    });
    htmlSections += '\n        <button type="submit" class="btn btn-primary">Cr\u00e9er</button>';
    htmlSections += '\n      </form>';
    htmlSections += '\n      <div id="feedback-' + sn + '" class="feedback"></div>';
    htmlSections += '\n    </section>';
  }

  if (r.getEp) {
    htmlSections += '\n    <section class="card" id="section-list-' + sn + '">';
    htmlSections += '\n      <div class="section-header">';
    htmlSections += '\n        <h2 class="card-title">\ud83d\udccb Liste ' + sanitizeStr(label) + '</h2>';
    htmlSections += '\n        <div class="toolbar no-print">';
    htmlSections += '\n          <button data-refresh="' + sn + '" class="btn btn-secondary">\u21bb Actualiser</button>';
    htmlSections += '\n          <button data-csv="' + sn + '" class="btn btn-secondary">\u2b07 CSV</button>';
    htmlSections += '\n          <button data-print="' + sn + '" class="btn btn-secondary">\ud83d\udda8 PDF</button>';
    htmlSections += '\n        </div>';
