    'CONSERVER toutes les fonctions existantes (loadItems, showFeedback, escapeHtml, etc.).\n' +
    'AJOUTER les ameliorations demandees.\n\n' +
    'REGLE ABSOLUE : Retourner UNIQUEMENT un JSON valide.\n' +
    'FORMAT :\n{\n  "agent": "frontend",\n  "app_js": "// code app.js ameliore complet"\n}\n\n' +
    'REGLES :\n' +
    '1. Conserver toutes les fonctions loadItems_*, showFeedback, escapeHtml\n' +
    '2. Conserver tous les addEventListener DOMContentLoaded\n' +
    '3. Ajouter les ameliorations demandees\n' +
    '4. Code syntaxiquement valide — pas de template literals, utiliser concatenation\n' +
    '5. Pas d apostrophes dans les strings — utiliser des guillemets doubles';

  var usrPrompt = 'PROMPT D\'AMELIORATION :\n' + improvePrompt + '\n\n' +
    instrText +
    'CODE APP.JS DE BASE (a ameliorer) :\n' + appJs + '\n\n' +
    'CODE INDEX.HTML DE BASE :\n' + html + '\n\n' +
    'Retourne UNIQUEMENT le JSON avec app_js ameliore.';

  return [{ json: {
    mode: 'llm_improve',
    systemPrompt: sysPrompt,
    userPrompt: usrPrompt,
    html_skeleton: html,
    css_content: css,
    _app_js_base: appJs,
    _login_html: loginHtml,
    _inp: inp
  } }];
}

// ── MODE NORMAL — retourner directement le code déterministe ──────────
return [{ json: { ...inp, mode: 'deterministic', html_skeleton: html, css_content: css, _app_js: appJs, _login_html: loginHtml } }];

const buildData = $input.first().json;
const files = [];
const errors = [];

if (!buildData.html_skeleton || !buildData._app_js) errors.push('Fichiers frontend incomplets');
if (String(buildData._app_js || '').includes('<div class="') && String(buildData._app_js || '').includes('onclick=')) {
  errors.push('app.js contient encore des fragments HTML injectés de façon risquée');
}

files.push({ path: 'frontend/index.html', content: buildData.html_skeleton || '' });
files.push({ path: 'frontend/style.css', content: buildData.css_content || '' });
files.push({ path: 'frontend/app.js', content: buildData._app_js || '' });
if (buildData._login_html) files.push({ path: 'frontend/login.html', content: buildData._login_html });

return [{ json: { agent: 'frontend', task_id: buildData.task_id || 'unknown', files, errors } }];

const input = $input.first().json;
const files = input.files || [];
const errors = input.errors || [];
const status = files.length > 0 && errors.length === 0 ? 'PASS' : 'FAIL';
return [{ json: { _version: '6.19', agent: 'Agent FRONTEND', task_id: input.task_id || 'unknown', status, global_score: status === 'PASS' ? 100 : 0, approved_for_pipeline: status === 'PASS', language: 'javascript', critical_issues: errors.map(e => ({ severity: 'high', description: String(e) })), warnings: [], recommendations: status === 'PASS' ? ['Frontend déterministe et validé'] : ['Corriger les erreurs bloquantes'], summary: status === 'PASS' ? `${files.length} fichier(s) frontend généré(s)` : 'Échec de génération frontend', dimensions: { security: { score: status === 'PASS' ? 100 : 0 }, quality: { score: status === 'PASS' ? 100 : 0 } }, timestamp: new Date().toISOString(), files } }];

const inp = $input.first().json;
const mode = inp.mode || 'deterministic';

if (mode === 'llm_improve') {
